#!/usr/bin/env python3
"""Emit libavcodec/vp9_kf_realdata_wbtest.mbt from .scratch/vp9k/vp9_kf_vectors.py.txt"""

import ast
import io
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, '..', '.scratch', 'vp9k', 'vp9_kf_vectors.py.txt')
OUT = os.path.join(HERE, '..', 'libavcodec', 'vp9_kf_realdata_wbtest.mbt')

with io.open(SRC, 'r', encoding='utf-8') as f:
    data = ast.literal_eval(f.read())

names = list(data.keys())
header = '''///|
/// VP9 keyframe decoder real-world vectors: five all-intra libvpx-vp9 streams
/// generated by docker `linuxserver/ffmpeg:9.0.2` (see
/// `scripts/_gen_vp9_kf_vectors.py`).  Expected values are the reference
/// decoder's per-frame yuv420p MD5s over the same bytes.
///
/// Reproduce with:
/// ```text
/// ffmpeg -f lavfi -i testsrc2=size=WxH:rate=10:duration=N -c:v libx264 \\
///        -preset ultrafast -pix_fmt yuv420p src.mp4
/// ffmpeg -i src.mp4 -c:v libvpx-vp9 -pix_fmt yuv420p -an -frames:v N \\
///        -g 1 [-q:v Q | -lossless 1 | -tile-columns 2 -tile-rows 1] out.ivf
/// ffmpeg -v quiet -i out.ivf -f rawvideo -pix_fmt yuv420p -   # MD5 per frame
/// ```
///
/// Original FFmpeg code is LGPL-2.1-or-later; the vectors are libre test data.
'''

parts = [header]
for name in names:
    st = data[name]
    w, h = st['size']
    parts.append('///|')
    parts.append("/// `%s`: %dx%d, %d keyframes." % (name, w, h, len(st['md5'])))
    parts.append('let vp9_kf_%s_size : (Int32, Int32) = (%d, %d)' % (name, w, h))
    parts.append('')
    parts.append('///|')
    parts.append('let vp9_kf_%s_md5 : Array[String] = [' % name)
    for m in st['md5']:
        parts.append('  "%s",' % m)
    parts.append(']')
    parts.append('')
    parts.append('///|')
    parts.append('let vp9_kf_%s_frames : Array[Bytes] = [' % name)
    for hx in st['frames']:
        # escape every byte as \xHH, chunk the literal into lines
        esc = ''.join('\\x%02x' % b for b in bytes.fromhex(hx))
        chunks = [esc[i:i + 48] for i in range(0, len(esc), 48)]
        expr = '  ' + ' +\n  '.join('b"%s"' % c for c in chunks) + ','
        parts.append(expr)
    parts.append(']')
    parts.append('')

with io.open(OUT, 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(parts))
print('wrote', os.path.normpath(OUT))
